import {C,G,blackHole,scenario,step,energy,body,mergeCollisions} from './physics.mjs';
export function checks(){let results=[];function check(n,ok){results.push({name:n,ok})}let b=blackHole(C.sun);check('Sonnenmasse: rₛ ≈ 2,953 km',Math.abs(b.radius/2953.34-1)<.001);check('Sonnenmasse: T ≈ 6,17 × 10⁻⁸ K',Math.abs(b.temperature/6.17e-8-1)<.002);check('Sonnenmasse: P ≈ 9,01 × 10⁻²⁹ W',Math.abs(b.power/9.01e-29-1)<.002);check('Sonnenmasse: τ ≈ 2,10 × 10⁶⁷ Jahre',Math.abs(b.lifetime/C.year/2.10e67-1)<.003);check('Erdmasse: rₛ ≈ 8,87 mm',Math.abs(blackHole(C.earth).radius/.00887-1)<.002);check('10⁹ kg: τ ≈ 2665 Jahre',Math.abs(blackHole(1e9).lifetime/C.year/2665-1)<.002);let bs=[body('S','star',1,0,0,0,0,'white'),body('E','planet',C.earth/C.sun,1,0,0,Math.sqrt(G),'blue')],e0=energy(bs);for(let t=0;t<365.25;t+=.05)step(bs,.05);check('Erdbahn nach 1 Jahr: Positionsfehler < 0,001 AU',Math.hypot(bs[1].x-1,bs[1].y)<.001);check('Erdbahn: relative Energiedrift < 10⁻⁷',Math.abs((energy(bs)-e0)/e0)<1e-7);let cs=[body('a','star',1,0,0,2,0,'white'),body('b','star',2,0,0,-1,0,'white')];mergeCollisions(cs);check('Kollision: Masse und Impuls erhalten',cs.length===1&&cs[0].m===3&&cs[0].vx===0);let ss=scenario('solar');check('Sonnensystem: Sonne + 8 Planeten',ss.length===9);return results}
